import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { addLocalDays, createTranslator, epochOf, formatClock, formatInstant, formatLocalDate, formatLocalDateShort, formatLocalDayMonth, instantFromEpoch, isCalendarDate, localDateInZone, nowEpoch, weekdayNames, zoneCity, type Translator } from "@dcortex/canvas-format";
import type { ApiClient } from "../api/client.js";
import { connectEvents, type ConnectEventsOptions } from "../api/events.js";
import { operationalZone } from "../api/readPlane.js";
import { messages } from "../i18n/messages.js";
import { taskCardSubtitle } from "../taskCard.js";
import { CheckInAlertModal, ConnectionAlertModal } from "../desk/DeskAlertModal.js";
import { rowIdentity } from "../desk/rowIdentity.js";
import { DCORTEX_MARK } from "../brand.js";
import { TenantMark } from "./TenantMark.js";
import { FlightDetail } from "./FlightDetail.js";
import { TaskModal } from "./TaskModal.js";
import { useRailAccess } from "../railAccess.js";
import { DocExpiryDetail } from "./DocExpiryDetail.js";
import { flightsPath, placeName, type AirportList, type OpsFlight } from "./opsApi.js";
import { setCheckInReplacementHandler } from "../screens/checkInGapActions.js";
import { RadarScope, type ScopeAxis, type ScopeRing } from "./RadarScope.js";
import {
  DEPARTURE_BANDS_HOURS,
  DEPARTURE_CORE_RADIUS,
  RADAR_AXES,
  RING_HOURS,
  RINGS,
  SWEEP_SECONDS,
  TASK_AXIS,
  arrivalBins,
  badgeCounts,
  checkInDepartureItems,
  checkInId,
  checkInItems,
  connectionDepartureItems,
  connectionId,
  connectionItems,
  dayBounds,
  departureItems,
  departureRadius,
  expiryRows,
  flightItems,
  inView,
  isNew,
  radiusFor,
  summarize,
  taskItems,
  uncrewedFlightItems,
  withoutCheckInTasks,
  type AxisId,
  type RadarCheckInGap,
  type RadarConnection,
  type RadarExpiryDocument,
  type RadarFlight,
  type RadarItem,
  type RadarMode,
  type RadarTask,
  type TileView,
} from "./radarModel.js";
import { getRadarSession, radarSessionKey, writeRadarSession, type RadarSessionReads } from "./radarSessionCache.js";
import "./radar.css";

/** Spokes and chips left off the screen for now: document expiry is hidden while that feature is reworked. Nothing else about the
 * Radar changes, and All never counted documents (they are not feed items). */
const HIDDEN_AXES: ReadonlySet<AxisId> = new Set<AxisId>(["expiry"]);

/** The Radar screen (knowledge-base/features/ops-control-panel.md §6, §6b): crew disruptions on a feed and a 24-hour
 * radar, in the approved design's look — placed by when they arrived (arrivals, the default) or by when their flight
 * departs (departures). Live: every `tasks-changed` on /api/events re-reads the tasks; flights,
 * the expiry badge and the turnaround read behind the connection items (§6c) are re-read every minute (paused while the tab is hidden). A revisit hydrates from a
 * session cache then revalidates in the background. A lost stream or a failed read keeps the last data and says so.
 * Every number on the screen is read from the BFF. Views only. */

const SLOW_READ_MS = 60_000;
const CLOCK_TICK_MS = 1_000;
const DAY_MS = 86_400_000;
/** The flight map's track starts 2 h before now. The Uncrewed list keeps that day and the two after it. */
const UNCREWED_LOOKBACK_MS = 2 * 60 * 60 * 1000;
const UNCREWED_DAYS = 3;

type RenderCtx = { timezone: string; locale: string; currency: string };
type Reads = RadarSessionReads;

/** The turnaround reads of three days as one: each breach tagged with its day, a connection seen on two days kept once. */
function mergeTurnaround(day: string, answers: { day: string; body: unknown }[]): Reads["turnaround"] {
  const byId = new Map<string, RadarConnection>();
  const summary = { warning: 0, critical: 0 };
  for (const { day: d, body } of answers) {
    const read = body as Reads["turnaround"];
    summary.warning += read?.summary?.warning ?? 0;
    summary.critical += read?.summary?.critical ?? 0;
    for (const b of read?.breaches ?? []) {
      const row = { ...b, day: d };
      if (!byId.has(connectionId(row))) byId.set(connectionId(row), row);
    }
  }
  return { day, breaches: [...byId.values()], summary };
}

/** The check-in gap reads of three days as one, each gap tagged with its day. */
function mergeCheckIns(day: string, answers: { day: string; body: unknown }[]): Reads["checkIns"] {
  const gaps: RadarCheckInGap[] = [];
  for (const { day: d, body } of answers) for (const g of (body as Reads["checkIns"])?.gaps ?? []) gaps.push({ ...g, day: d });
  return { day, gaps };
}

/** Drop ahead flights when the viewer is not in departures — they belong to that mode's window only. */
function readsForMode(reads: Reads, mode: RadarMode): Reads {
  if (mode === "departures" || reads.aheadFlights === undefined) return reads;
  const { aheadFlights: _ahead, ...rest } = reads;
  return rest;
}

/** "HH:MM" in `zone`. Digits read the same in every locale, so the clock is formatted once, without the zone suffix. */
function hhmm(iso: string, zone: string): string {
  return formatInstant(iso, { timezone: zone, locale: "en-GB", currency: "USD" }, { style: "time" }).slice(0, 5);
}

/** "Wed 30 Sep": the weekday from the date itself (1970-01-01 was a Thursday), in the three-letter form ("Tue", not "Tu"), the rest
 * from the day-first convention. */
function dayLabel(day: string, locale: string): string {
  const dow = (((Math.floor(epochOf(`${day}T12:00:00Z`) / DAY_MS) + 4) % 7) + 7) % 7;
  return `${weekdayNames(locale, 3)[dow]} ${formatLocalDayMonth(day)}`;
}

const RADAR_MODE_STORAGE_KEY = "dcortex.radarMode";
const isMode = (v: unknown): v is RadarMode => v === "arrivals" || v === "departures";

/** The viewer's remembered mode — a per-viewer display convenience. Storage can be blocked or absent; the page then
 * simply opens in arrivals. */
function storedMode(): RadarMode | undefined {
  try {
    const value = globalThis.localStorage?.getItem(RADAR_MODE_STORAGE_KEY);
    return isMode(value) ? value : undefined;
  } catch {
    return undefined;
  }
}

function storeMode(mode: RadarMode): void {
  try {
    globalThis.localStorage?.setItem(RADAR_MODE_STORAGE_KEY, mode);
  } catch {
    // blocked or full: the choice still applies to this page view
  }
}

function age(t: Translator, minutes: number): string {
  const m = Math.max(0, Math.floor(minutes));
  return m < 60 ? t("ops.radar.ageMin", { n: m }) : t("ops.radar.ageHM", { h: Math.floor(m / 60), m: String(m % 60).padStart(2, "0") });
}

/** Arrivals: how long ago it arrived. Departures: how long until its flight leaves, or how long overdue. */
function when(t: Translator, item: RadarItem): string {
  if (item.untilMinutes === undefined) return age(t, item.ageMinutes);
  return item.untilMinutes < 0 ? t("ops.radar.overdue", { t: age(t, -item.untilMinutes) }) : t("ops.radar.untilIn", { t: age(t, item.untilMinutes) });
}

function title(t: Translator, item: RadarItem): string {
  if (item.gapKind !== undefined) return `${t("ops.radar.axis.checkin")} — ${item.subject ?? item.flight ?? t("ops.radar.untitled")}`;
  if (item.kind === "flight") return `${item.flight} ${item.route}`;
  const subject = item.subject ?? taskCardSubtitle(item.taskKey, item.operationalDate) ?? item.route ?? t("ops.radar.untitled");
  return `${t(`ops.radar.axis.${item.axis}`)} — ${subject}`;
}

/** The list's second line: a delay's minutes, or a task's route and day. A clock the row already shows is not repeated. */
function listDetail(t: Translator, item: RadarItem, ctx: RenderCtx): string | undefined {
  if (item.gapKind !== undefined) {
    const flight = `${item.flight ?? ""} ${item.route ?? ""}`.trim();
    return item.lateMinutes !== undefined ? `${flight} · ${t("ops.radar.fact.delayValue", { n: item.lateMinutes })}` : flight;
  }
  if (item.axis === "connection") return item.gapMinutes !== undefined && item.warningMinutes !== undefined ? t("ops.radar.connectionDetail", { gap: item.gapMinutes, min: item.warningMinutes }) : undefined;
  if (item.kind === "flight") {
    if (item.axis === "delay" && item.delayMinutes !== undefined) return t("ops.radar.fact.delayValue", { n: item.delayMinutes });
    if (item.axis === "uncrewed" && item.operationalDate) return formatLocalDate(item.operationalDate, ctx);
    return undefined;
  }
  const parts = [item.subject && item.route ? item.route : undefined, item.operationalDate ? formatLocalDate(item.operationalDate, ctx) : undefined].filter((p) => p !== undefined);
  return parts.length > 0 ? parts.join(" · ") : undefined;
}

function pill(item: RadarItem): string {
  if (item.gapKind !== undefined) return item.gapKind === "MISSING_CHECK_IN" ? "missing" : item.gapKind === "LATE_CHECK_IN" ? "late" : "manual";
  if (item.axis === "connection") return item.severity === "CRITICAL" ? "critical" : "warning";
  if (item.kind === "flight") {
    if (item.axis === "cancel") return "cancelled";
    if (item.axis === "uncrewed") return "uncrewed";
    return "delayed";
  }
  return item.state === "action" ? "new" : item.state === "open" ? "ack" : "resolved";
}

function clock(iso: string, ctx: RenderCtx): string {
  return formatInstant(iso, ctx, { style: "time" });
}

/** The name the locked card and a task row lead with. A blip keeps `title`, which still names the disruption type. */
function lockTitle(t: Translator, item: RadarItem): string {
  if (item.gapKind !== undefined) return item.position ? `${item.subject ?? item.flight ?? ""} (${item.position})` : (item.subject ?? item.flight ?? "");
  if (item.kind === "flight") return item.flight ?? "";
  return item.subject ?? taskCardSubtitle(item.taskKey, item.operationalDate) ?? item.route ?? t("ops.radar.untitled");
}

/** Facts from the record, in pairs so the card stays short. A clock that repeats the scheduled departure is left out. */
function lockFacts(t: Translator, item: RadarItem, ctx: RenderCtx): { label: string; value: string }[] {
  if (item.gapKind !== undefined) {
    return [
      ...(item.flight ? [{ label: t("ops.radar.fact.flight"), value: item.flight }] : []),
      ...(item.reportTime ? [{ label: t("ops.radar.fact.report"), value: clock(item.reportTime, ctx) }] : []),
      ...(item.checkInTime ? [{ label: t("ops.radar.fact.checkIn"), value: clock(item.checkInTime, ctx) }] : []),
      ...(item.lateMinutes !== undefined ? [{ label: t("ops.radar.fact.late"), value: t("ops.radar.fact.delayValue", { n: item.lateMinutes }) }] : []),
      ...(item.scheduledDeparture ? [{ label: t("ops.radar.fact.scheduledDep"), value: clock(item.scheduledDeparture, ctx) }] : []),
    ];
  }
  if (item.axis === "connection") {
    return [
      ...(item.gapMinutes !== undefined ? [{ label: t("ops.radar.fact.groundTime"), value: t("ops.radar.fact.groundTimeValue", { n: item.gapMinutes }) }] : []),
      ...(item.warningMinutes !== undefined && item.criticalMinutes !== undefined
        ? [{ label: t("ops.radar.fact.minimum"), value: t("ops.radar.fact.minimumValue", { warning: item.warningMinutes, critical: item.criticalMinutes }) }]
        : []),
      ...(item.inboundArrival ? [{ label: t("ops.radar.fact.inboundArr"), value: clock(item.inboundArrival, ctx) }] : []),
      ...(item.outboundDeparture ? [{ label: t("ops.radar.fact.outboundDep"), value: clock(item.outboundDeparture, ctx) }] : []),
      ...(item.pairing ? [{ label: t("ops.radar.fact.pairing"), value: item.pairing }] : []),
      ...(item.crew && item.crew.length > 0 ? [{ label: t("ops.radar.fact.crew"), value: item.crew.join(", ") }] : []),
    ];
  }
  if (item.kind === "flight") {
    const facts: { label: string; value: string }[] = [];
    if (item.axis === "delay" && item.delayMinutes !== undefined) {
      facts.push({ label: t("ops.radar.fact.delay"), value: t("ops.radar.fact.delayValue", { n: item.delayMinutes }) });
      if (item.scheduledDeparture === undefined || epochOf(item.at) !== epochOf(item.scheduledDeparture)) {
        facts.push({ label: t("ops.radar.fact.departure"), value: clock(item.at, ctx) });
      }
    }
    if (item.scheduledDeparture) facts.push({ label: t("ops.radar.fact.scheduledDep"), value: clock(item.scheduledDeparture, ctx) });
    if (item.scheduledArrival) facts.push({ label: t("ops.radar.fact.scheduledArr"), value: clock(item.scheduledArrival, ctx) });
    return facts;
  }
  return [
    ...(item.subject && item.route ? [{ label: t("ops.radar.fact.route"), value: item.route }] : []),
    ...(item.operationalDate ? [{ label: t("ops.radar.fact.day"), value: formatLocalDate(item.operationalDate, ctx) }] : []),
    { label: t("ops.radar.fact.received"), value: clock(item.at, ctx) },
    ...(item.departureAt ? [{ label: t("ops.radar.fact.departure"), value: clock(item.departureAt, ctx) }] : []),
  ];
}

function requestScreenFullscreen(el: HTMLElement): void {
  const request = el.requestFullscreen as ((this: HTMLElement) => Promise<void>) | undefined;
  if (request) void request.call(el).catch(() => undefined);
}

/** The mode's note: the one part of the scope's heading that may be cut short, with its full text on hover. */
function ToolbarNote({ text }: { text: string }) {
  return (
    <span className="radar-toolbar-note" data-testid="radar-toolbar-note" title={text}>
      {text}
    </span>
  );
}

export function Radar({
  client,
  connect = connectEvents,
  now = nowEpoch,
  requestFullscreen = requestScreenFullscreen,
  onUnauthenticated,
  onPresentation,
}: {
  client: ApiClient;
  connect?: (opts: ConnectEventsOptions) => { close: () => void };
  now?: () => number;
  requestFullscreen?: (el: HTMLElement) => void;
  onUnauthenticated?: () => void;
  /** Called once the first data read has landed, which is when the presentation context (the customer's name) is known. */
  onPresentation?: () => void;
}) {
  const presentation = client.presentation();
  const ctx: RenderCtx = presentation ?? { timezone: "UTC", locale: "en", currency: "USD" };
  const t = createTranslator(ctx.locale, messages);
  const zone = operationalZone(client) ?? ctx.timezone;
  const [params, setParams] = useSearchParams();
  const [remembered, setRemembered] = useState(storedMode);
  const modeParam = params.get("mode");
  const mode: RadarMode = isMode(modeParam) ? modeParam : (remembered ?? "arrivals");
  const modeRef = useRef(mode);
  // Seed from the session cache so a revisit paints before the background revalidate lands.
  const [reads, setReads] = useState<Reads>(() => {
    const today = localDateInZone(now(), zone);
    const dayParam = params.get("day");
    const day = dayParam && isCalendarDate(dayParam) && dayParam < today ? dayParam : undefined;
    const snap = getRadarSession(radarSessionKey(day));
    return snap ? readsForMode(snap.reads, mode) : {};
  });
  const [failed, setFailed] = useState<Record<string, boolean>>({});
  const [streamStale, setStreamStale] = useState(false);
  const [nowMs, setNowMs] = useState(() => now());
  const [lastUpdate, setLastUpdate] = useState<number | undefined>(() => {
    const today = localDateInZone(now(), zone);
    const dayParam = params.get("day");
    const day = dayParam && isCalendarDate(dayParam) && dayParam < today ? dayParam : undefined;
    return getRadarSession(radarSessionKey(day))?.lastUpdate;
  });
  const [filter, setFilter] = useState<AxisId | undefined>();
  const [view, setView] = useState<TileView | undefined>();
  const [selectedId, setSelectedId] = useState<string | undefined>();
  const [popupFor, setPopupFor] = useState<string | undefined>();
  const [docDetail, setDocDetail] = useState<RadarExpiryDocument | undefined>();
  // the event list is closed until something asks for it: a tile, a chip, a spoke, or All
  const [showAll, setShowAll] = useState(false);
  const [scrub, setScrub] = useState<number | undefined>();
  const [ackFailed, setAckFailed] = useState<string | undefined>();
  const [ackingId, setAckingId] = useState<string | undefined>();
  const [detailFlight, setDetailFlight] = useState<OpsFlight | undefined>();
  const [detailRecheck, setDetailRecheck] = useState(false);
  const [detailFindPosition, setDetailFindPosition] = useState<string | undefined>();
  const [detailPlaces, setDetailPlaces] = useState<ReadonlyMap<string, { city?: string; full: string }>>(() => new Map());
  const [openFailedId, setOpenFailedId] = useState<string | undefined>();
  const [openingId, setOpeningId] = useState<string | undefined>();
  const t0 = useRef(now());
  const screenRef = useRef<HTMLDivElement>(null);
  const lastSlowAt = useRef(0);
  // A tick or signal that lands while the same read is still out is not a reason to ask again: each one that stacked up
  // held a BFF connection for the whole of a slow read, and the backlog is what timed the console out.
  const slowInFlight = useRef(false);
  const tasksRun = useRef<{ start: number | undefined; again: boolean } | undefined>(undefined);
  // undefined = first mount for this instance; only a real day change drops the previous day's reads
  const prevReplayStart = useRef<number | undefined | null>(null);
  const prevModeWindow = useRef<{ mode: RadarMode; start: number | undefined; end: number | undefined } | null>(null);

  const persistReads = useCallback(
    (next: Reads, taskUpdatedAt?: number) => {
      const today = localDateInZone(now(), zone);
      const dayParam = params.get("day");
      const day = dayParam && isCalendarDate(dayParam) && dayParam < today ? dayParam : undefined;
      writeRadarSession(radarSessionKey(day), next, {
        mode: modeRef.current,
        fetchedAt: now(),
        ...(taskUpdatedAt !== undefined ? { lastUpdate: taskUpdatedAt } : {}),
      });
    },
    [now, params, zone],
  );

  const read = useCallback(
    // `isCurrent`: the read is for a window that may no longer be the one on screen; an answer for another is dropped
    async <K extends keyof Reads>(key: K, path: string, pick: (body: unknown) => Reads[K], isCurrent: () => boolean = () => true) => {
      try {
        const body = await client.get<unknown>(path);
        if (!isCurrent()) return;
        const value = pick(body);
        const at = key === "tasks" ? now() : undefined;
        setReads((r) => {
          const next = { ...r, [key]: value };
          persistReads(next, at);
          return next;
        });
        setFailed((f) => ({ ...f, [key]: false }));
        if (at !== undefined) setLastUpdate(at);
      } catch (err) {
        if (isCurrent() && !(err instanceof Error && err.message === "unauthenticated")) setFailed((f) => ({ ...f, [key]: true }));
      }
    },
    [client, now, persistReads],
  );
  /** The operational day at `at`, in the zone known at the moment of asking: the first reads go out before any answer has
   * carried the tenant's zone, so a read that names a day checks it again once its own answer has landed. */
  const operationalDay = useCallback((at: number) => localDateInZone(at, operationalZone(client) ?? client.presentation()?.timezone ?? "UTC"), [client]);
  /** The turnaround and check-in reads are per operational day; the Radar's windows run 24 h either side of now, so it reads
   * yesterday, today and tomorrow and tags each row with its day. */
  const readDays = useCallback(
    async <K extends "turnaround" | "checkIns">(key: K, pathFor: (day: string) => string, merge: (day: string, answers: { day: string; body: unknown }[]) => Reads[K]) => {
      const at = now();
      const readAround = (day: string) => Promise.all([addLocalDays(day, -1), day, addLocalDays(day, 1)].map(async (d) => ({ day: d, body: await client.get<unknown>(pathFor(d)) })));
      try {
        let day = operationalDay(at);
        let answers = await readAround(day);
        const settled = operationalDay(at);
        if (settled !== day) {
          day = settled;
          answers = await readAround(day);
        }
        const value = merge(day, answers);
        setReads((r) => {
          const next = { ...r, [key]: value };
          persistReads(next);
          return next;
        });
        setFailed((f) => ({ ...f, [key]: false }));
      } catch (err) {
        if (!(err instanceof Error && err.message === "unauthenticated")) setFailed((f) => ({ ...f, [key]: true }));
      }
    },
    [client, now, operationalDay, persistReads],
  );
  // the start of the replayed day, or undefined while live: what the reads below are for
  const replayWanted = useRef<number | undefined>(undefined);

  // days: a past day replays as of its centre (KB §6 "Days"); today, or any day not in the past, is live
  const today = localDateInZone(nowMs, zone);
  const dayParam = params.get("day");
  const replayDay = dayParam && isCalendarDate(dayParam) && dayParam < today ? dayParam : undefined;
  const bounds = replayDay ? dayBounds(replayDay, zone) : undefined;
  const dayMinutes = bounds ? (bounds.endMs - bounds.startMs) / 60_000 : 0;
  const centreMinutes = bounds ? Math.min(scrub ?? dayMinutes, dayMinutes) : 0;
  const centreMs = bounds ? bounds.startMs + centreMinutes * 60_000 : nowMs;
  /** The wall clock at `minutes` into the replayed day: counted from the day's real start, so a 23 or 25 hour day reads right. The end is
   * 24:00, which an instant cannot say (it is the next day's 00:00). */
  const clockAt = (minutes: number) => (bounds && minutes < dayMinutes ? hhmm(instantFromEpoch(bounds.startMs + minutes * 60_000), zone) : "24:00");
  const resetView = () => {
    setSelectedId(undefined);
    setFilter(undefined);
    setView(undefined);
    setShowAll(false);
  };
  const goToDay = (day: string | undefined) => {
    setScrub(undefined);
    resetView();
    setParams((prev) => {
      const next = new URLSearchParams(prev);
      if (day === undefined) next.delete("day");
      else next.set("day", day);
      return next;
    });
  };

  /** The open tasks and the closed ones the window can show: a task resolved before (the window's start - 24 h) was received before every
   * window the screen can draw (live: the last 24 h; a replay: any time in the day), so the read need not carry it. */
  const readTasks = useCallback(async () => {
    const start = replayWanted.current;
    const running = tasksRun.current;
    // a signal during a read of the same window may describe a change that read missed: read once more after it, not once per signal
    if (running && running.start === start) {
      running.again = true;
      return;
    }
    const run = { start, again: false };
    tasksRun.current = run;
    try {
      do {
        run.again = false;
        const closedSince = instantFromEpoch((start ?? now()) - DAY_MS);
        await read("tasks", `/api/tasks?closedSince=${encodeURIComponent(closedSince)}`, (b) => (b as { tasks?: RadarTask[] })?.tasks ?? [], () => replayWanted.current === start);
      } while (run.again && replayWanted.current === start);
    } finally {
      if (tasksRun.current === run) tasksRun.current = undefined;
    }
  }, [read, now]);
  /** Departures mode only: the 24 hours after the centre's window — after now live, after the day in a replay. */
  const readAhead = useCallback(
    (fromMs: number | undefined) => {
      const start = replayWanted.current;
      return read(
        "aheadFlights",
        flightsPath({ from: instantFromEpoch(fromMs ?? now()), hours: 24 }),
        (b) => (b as { flights?: RadarFlight[] })?.flights ?? [],
        () => replayWanted.current === start && modeRef.current === "departures",
      );
    },
    [read, now],
  );
  /** The Uncrewed list: the flight map's 24 h track, then the next days. One window is the API's maximum. */
  const readUncrewed = useCallback(
    async (replayStartMs: number | undefined) => {
      const start = replayWanted.current;
      const origin = replayStartMs ?? now() - UNCREWED_LOOKBACK_MS;
      try {
        const windows = await Promise.all(
          Array.from({ length: UNCREWED_DAYS }, (_, i) =>
            client.get<{ flights?: RadarFlight[] }>(flightsPath({ from: instantFromEpoch(origin + i * DAY_MS), hours: 24 })),
          ),
        );
        if (replayWanted.current !== start) return;
        const byId = new Map<string, RadarFlight>();
        for (const window of windows) for (const flight of window?.flights ?? []) byId.set(flight.legId, flight);
        const uncrewedFlights = [...byId.values()];
        setReads((r) => {
          const next = { ...r, uncrewedFlights };
          persistReads(next);
          return next;
        });
        setFailed((f) => ({ ...f, uncrewedFlights: false }));
      } catch (err) {
        if (replayWanted.current === start && !(err instanceof Error && err.message === "unauthenticated")) setFailed((f) => ({ ...f, uncrewedFlights: true }));
      }
    },
    [client, now, persistReads],
  );
  const readSlow = useCallback(() => {
    if (slowInFlight.current) return;
    slowInFlight.current = true;
    lastSlowAt.current = now();
    const at = lastSlowAt.current;
    const day = operationalDay(at);
    const reads = [
      read("flights", flightsPath({ from: instantFromEpoch(at - DAY_MS), hours: 24 }), (b) => (b as { flights?: RadarFlight[] })?.flights ?? []),
      read("expiry", `/api/read/document-expiry?fromDate=${day}&toDate=${addLocalDays(day, 30)}`, (b) => b as Reads["expiry"]),
      readDays("turnaround", (d) => `/api/read/turnaround-risks?date=${d}`, mergeTurnaround),
      readDays("checkIns", (d) => `/api/read/crew-check-in-gaps?date=${d}`, mergeCheckIns),
    ];
    if (replayWanted.current === undefined) reads.push(readUncrewed(undefined));
    if (modeRef.current === "departures" && replayWanted.current === undefined) reads.push(readAhead(undefined));
    void Promise.allSettled(reads).finally(() => {
      slowInFlight.current = false;
    });
  }, [now, operationalDay, read, readAhead, readDays, readUncrewed]);

  /** A replay's flights: the 24 hours before the day and the day itself, read once per day chosen. */
  const readReplayFlights = useCallback(
    async (startMs: number) => {
      // another day was chosen while this read was in flight: its answer is for a day no longer on screen
      const current = () => replayWanted.current === startMs;
      try {
        const [before, during] = await Promise.all(
          [startMs - DAY_MS, startMs].map((from) => client.get<{ flights?: RadarFlight[] }>(flightsPath({ from: instantFromEpoch(from), hours: 24 }))),
        );
        if (!current()) return;
        const byId = new Map([...(before?.flights ?? []), ...(during?.flights ?? [])].map((f) => [f.legId, f]));
        const replayFlights = [...byId.values()];
        setReads((r) => {
          const next = { ...r, replayFlights };
          persistReads(next);
          return next;
        });
        setFailed((f) => ({ ...f, replayFlights: false }));
      } catch (err) {
        if (current() && !(err instanceof Error && err.message === "unauthenticated")) setFailed((f) => ({ ...f, replayFlights: true }));
      }
    },
    [client, persistReads],
  );
  const replayStart = bounds?.startMs;
  useEffect(() => {
    replayWanted.current = replayStart;
    const first = prevReplayStart.current === null;
    const changed = !first && prevReplayStart.current !== replayStart;
    prevReplayStart.current = replayStart;
    // the previous day's flights and tasks belong to that day — drop them only when the day actually changes
    if (changed) {
      setReads((r) => {
        if (r.replayFlights === undefined && r.tasks === undefined) return r;
        const { replayFlights: _previousFlights, tasks: _previousTasks, ...rest } = r;
        return rest;
      });
      setFailed((f) => (f.replayFlights || f.tasks ? { ...f, replayFlights: false, tasks: false } : f));
      const snap = getRadarSession(radarSessionKey(replayDay));
      if (snap) {
        setReads((r) => readsForMode({ ...r, ...snap.reads }, modeRef.current));
        if (snap.lastUpdate !== undefined) setLastUpdate(snap.lastUpdate);
      }
    }
    void readTasks();
    if (replayStart !== undefined) {
      void readReplayFlights(replayStart);
      void readUncrewed(replayStart);
    }
  }, [replayStart, replayDay, readReplayFlights, readTasks, readUncrewed]);

  const replayEnd = bounds?.endMs;
  useEffect(() => {
    modeRef.current = mode;
    const window = { mode, start: replayStart, end: replayEnd };
    const first = prevModeWindow.current === null;
    const prev = prevModeWindow.current;
    const changed = !first && prev !== null && (prev.mode !== window.mode || prev.start !== window.start || prev.end !== window.end);
    prevModeWindow.current = window;
    // the flights ahead belong to the window and the mode they were read for
    if (changed) {
      setReads((r) => {
        if (r.aheadFlights === undefined) return r;
        const { aheadFlights: _previous, ...rest } = r;
        return rest;
      });
      setFailed((f) => (f.aheadFlights ? { ...f, aheadFlights: false } : f));
    }
    // live, the first ahead read is the slow read's; a later change of mode or window, or a replay, reads it here
    if (mode === "departures" && (!first || replayEnd !== undefined)) void readAhead(replayEnd);
  }, [mode, replayStart, replayEnd, readAhead]);

  useEffect(() => {
    readSlow(); // the tasks are read by the effect above, which runs first on mount and again for each day chosen
    const stream = connect({ onTasksChanged: () => void readTasks(), onStale: setStreamStale, onUnauthenticated: () => onUnauthenticated?.() });
    const slow = setInterval(() => {
      if (document.visibilityState === "visible") readSlow();
    }, SLOW_READ_MS);
    const onVisible = () => {
      if (document.visibilityState !== "visible") return;
      if (now() - lastSlowAt.current >= SLOW_READ_MS) readSlow();
    };
    document.addEventListener("visibilitychange", onVisible);
    const clock = setInterval(() => setNowMs(now()), CLOCK_TICK_MS);
    return () => {
      stream.close();
      clearInterval(slow);
      clearInterval(clock);
      document.removeEventListener("visibilitychange", onVisible);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [client]);

  const hasRead = reads.tasks !== undefined;
  useEffect(() => {
    if (hasRead) onPresentation?.();
  }, [hasRead]); // eslint-disable-line react-hooks/exhaustive-deps

  const flightsRead = replayDay ? reads.replayFlights : reads.flights;
  const departureFlights = useMemo(() => [...new Map([...(flightsRead ?? []), ...(reads.aheadFlights ?? [])].map((f) => [f.legId, f])).values()], [flightsRead, reads.aheadFlights]);
  // the turnaround and check-in gaps reads are today's only, so a replay has no items from them (§6c, §6d)
  const breaches = replayDay ? undefined : reads.turnaround?.breaches;
  const checkInGaps = replayDay ? undefined : reads.checkIns?.gaps;
  // Uncrewed routes are the flight map's short flights (§6), so a shortage task is not a second, differently counted copy of them.
  const radarTasks = useMemo(
    () => withoutCheckInTasks(reads.tasks ?? [], checkInGaps, reads.checkIns?.day).filter((t) => !Object.hasOwn(TASK_AXIS, t.type) || TASK_AXIS[t.type] !== "uncrewed"),
    [reads.tasks, checkInGaps, reads.checkIns?.day],
  );
  const itemsAt = useCallback(
    (atMs: number) => {
      const tasks = taskItems(radarTasks, atMs);
      const connections = connectionItems(breaches, atMs);
      const checkIns = checkInItems(checkInGaps, atMs);
      return {
        items: [...tasks.items, ...flightItems(flightsRead ?? [], atMs), ...connections.items, ...checkIns.items].sort((a, b) => a.ageMinutes - b.ageMinutes),
        unplaced: tasks.unplaced,
        upcoming: { connection: connections.upcoming, checkin: checkIns.upcoming } as Partial<Record<AxisId, number>>,
      };
    },
    [radarTasks, flightsRead, breaches, checkInGaps],
  );
  const arrivals = useMemo(() => itemsAt(centreMs), [itemsAt, centreMs]);
  const departures = useMemo(
    () => {
      if (mode !== "departures") return undefined;
      const placed = departureItems(radarTasks, departureFlights, centreMs);
      const items = [...placed.items, ...connectionDepartureItems(breaches, centreMs), ...checkInDepartureItems(checkInGaps, centreMs)].sort(
        (a, b) => (a.untilMinutes ?? 0) - (b.untilMinutes ?? 0),
      );
      return { ...placed, items };
    },
    [mode, radarTasks, departureFlights, centreMs, breaches, checkInGaps],
  );
  const { items: placed, unplaced } = departures ?? arrivals;
  const uncrewedRows = useMemo(() => uncrewedFlightItems(reads.uncrewedFlights ?? [], centreMs), [reads.uncrewedFlights, centreMs]);
  // one list behind every number: All, the tiles, the chips and the spoke labels all count these rows
  const items = useMemo(
    () => (mode === "departures" ? [...placed, ...uncrewedRows].sort((a, b) => (a.untilMinutes ?? 0) - (b.untilMinutes ?? 0)) : [...placed, ...uncrewedRows]),
    [mode, placed, uncrewedRows],
  );
  const listing = items;
  const stripItems = useMemo(() => (bounds ? itemsAt(bounds.endMs).items : arrivals.items), [itemsAt, bounds?.endMs, arrivals.items]); // eslint-disable-line react-hooks/exhaustive-deps
  const counts = summarize(items);
  const badges = badgeCounts(reads.expiry);
  // the expiry spoke is a count, never a blip (RADAR_AXES), so its list doesn't come from `items` —
  // it's the documents read directly, soonest-first, not positioned by age like every other spoke's rows
  const expiryList = useMemo(() => expiryRows(reads.expiry?.documents), [reads.expiry]);
  // by event time, a connection whose inbound has not arrived yet, or a check-in not yet due, is counted on its spoke, never placed
  const upcoming: Partial<Record<AxisId, number>> = departures ? {} : arrivals.upcoming;
  // expiry has its own list (expiryList, below) and never has dial blips of its own — filtering to it would just
  // blank every other spoke's dots for no reason, so the scope stays unfiltered while it's the active filter
  const shown = listing.filter((i) => (filter === undefined || filter === "expiry" || i.axis === filter) && inView(i, view));
  // the scope draws what still needs someone — information (resolved, a short delay) stays in the feed; the Resolved tile shows it
  const onScope = view === "resolved" ? shown : shown.filter((i) => i.state !== "resolved");
  const bins = arrivalBins(stripItems);
  const binMax = Math.max(1, ...bins.map((b) => b.count));
  const selected = shown.find((i) => i.id === selectedId);
  // every item opens the card; a check-in gap's or a connection risk's card also offers Details, the desk's own popup over the Radar
  // (§6c, §6d). The popup belongs to the item it was opened from, so selecting another item leaves it closed.
  const detailGap = selected ? checkInGaps?.find((g) => checkInId(g) === selected.id) : undefined;
  const detailConnection = selected && !detailGap ? breaches?.find((c) => connectionId(c) === selected.id) : undefined;
  const popupOpen = popupFor !== undefined && popupFor === selected?.id;
  const popupGap = popupOpen ? detailGap : undefined;
  const popupConnection = popupOpen ? detailConnection : undefined;
  const closePopup = useCallback(() => setPopupFor(undefined), []);
  const stale = streamStale || Object.entries(failed).some(([key, bad]) => bad && key !== "uncrewedFlights" && (key !== "replayFlights" || replayDay !== undefined) && (key !== "aheadFlights" || mode === "departures"));
  // "nothing in the last 24 h" is only true once the tasks and the flights of the day on screen have both answered
  const loaded = reads.tasks !== undefined && flightsRead !== undefined;
  // departures places by the flights ahead too: until they have answered (or failed, which the stale banner says), an empty
  // list is not yet "nothing departing"
  const aheadPending = mode === "departures" && reads.aheadFlights === undefined && !failed.aheadFlights;
  const replayFlightsFailed = replayDay !== undefined && Boolean(failed.replayFlights);
  const loadFailed = !loaded && Boolean(failed.tasks || (replayDay ? failed.replayFlights : failed.flights));
  const updatedAgo = lastUpdate === undefined ? "—" : String(Math.max(0, Math.floor((nowMs - lastUpdate) / 1000)));
  const nowIso = instantFromEpoch(nowMs);

  const [taskModalId, setTaskModalId] = useState<string | undefined>();
  const access = useRailAccess();

  const acknowledge = async (taskId: string) => {
    setAckFailed(undefined);
    setAckingId(taskId);
    try {
      await client.post(`/api/tasks/${encodeURIComponent(taskId)}/acknowledge`, {});
    } catch (err) {
      if (!(err instanceof Error && err.message === "unauthenticated")) setAckFailed(taskId);
    } finally {
      setAckingId((cur) => (cur === taskId ? undefined : cur));
      void readTasks();
    }
  };

  /** Opens the flight modal over the Radar; `recheck` judges the rostered crew again, which is what offers Find replacement. */
  const showFlight = async (flight: OpsFlight, recheck: boolean, findPosition?: string) => {
    // The modal opens at once and shows its own loaders; the airport names fill in when they arrive.
    setDetailRecheck(recheck);
    setDetailFindPosition(findPosition);
    setDetailFlight(flight);
    let airports: AirportList | undefined;
    try {
      airports = await client.get<AirportList>("/api/reference/airports");
    } catch {
      airports = undefined;
    }
    const places = new Map<string, { city?: string; full: string }>();
    for (const airport of airports?.airports ?? []) places.set(airport.iata, { ...(airport.city ? { city: airport.city } : {}), full: placeName(airport) });
    setDetailPlaces(places);
  };

  /** A flight row's Open task: the flight is already in one of the radar's reads. A delayed one opens with the crew
   * re-checked on the delayed times. */
  const openHeldFlight = async (legId: string, axis: AxisId) => {
    setOpenFailedId(undefined);
    setOpeningId(legId);
    try {
      const held = axis === "delay" || axis === "cancel" ? [...(flightsRead ?? []), ...(reads.aheadFlights ?? [])] : (reads.uncrewedFlights ?? []);
      const flight = held.find((f) => f.legId === legId) as OpsFlight | undefined;
      if (!flight) {
        setOpenFailedId(legId);
        return;
      }
      await showFlight(flight, axis === "delay");
    } catch (err) {
      if (!(err instanceof Error && err.message === "unauthenticated")) setOpenFailedId(legId);
    } finally {
      setOpeningId((cur) => (cur === legId ? undefined : cur));
    }
  };

  /** A flight the radar's reads hold, by its number, route and scheduled departure (the first of that number and route without one). */
  const heldFlight = (flightNo: string, dep: string, arr: string, std: string | null): OpsFlight | undefined => {
    const pool = [...(flightsRead ?? []), ...(reads.aheadFlights ?? []), ...(reads.uncrewedFlights ?? [])] as OpsFlight[];
    const same = pool.filter((f) => `${f.carrier}${f.flightNumber}` === flightNo && f.origin.iata === dep && f.destination.iata === arr);
    const at = std ? epochOf(std) : undefined;
    return (at === undefined ? undefined : same.find((f) => epochOf(f.scheduled.departure) === at)) ?? same[0];
  };

  // Manage Crew Schedule on a check-in gap opens that flight with its replacement finder, over the gap's own dialog.
  useEffect(() => {
    setCheckInReplacementHandler((row) => {
      const flight = heldFlight(row.flight, row.dep, row.arr, row.std);
      if (!flight) return;
      setPopupFor(undefined);
      void showFlight(flight, true, row.position || undefined);
    });
    return () => setCheckInReplacementHandler(undefined);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- showFlight only reads `client` and sets state
  }, [flightsRead, reads.aheadFlights, reads.uncrewedFlights, client]);

  const axisLabel = (id: AxisId) => t(`ops.radar.axis.${id}`);
  // a filter change releases the lock: a locked card never outlives what is on screen
  const changeFilter = (next: AxisId | undefined) => {
    setSelectedId(undefined);
    setFilter(next);
  };
  const toggleFilter = (id: AxisId) => changeFilter(filter === id ? undefined : id);
  const clearFilters = () => {
    setSelectedId(undefined);
    setFilter(undefined);
    setView(undefined);
    setShowAll(false);
  };
  const filtered = filter !== undefined || view !== undefined;
  const listOpen = showAll || filtered;
  // All clears any filter and shows everything; pressed again on an unfiltered list, it closes it
  const pressAll = () => {
    setSelectedId(undefined);
    if (filtered) {
      setFilter(undefined);
      setView(undefined);
      setShowAll(true);
    } else setShowAll((open) => !open);
  };
  const toggleView = (id: TileView) => {
    setSelectedId(undefined);
    setView((v) => (v === id ? undefined : id));
  };
  const scopeAxes: ScopeAxis[] = RADAR_AXES.filter((a) => !HIDDEN_AXES.has(a.id)).map((a) => {
    if (a.badge) {
      const n = badges.expiry;
      return { id: a.id, label: axisLabel(a.id), countText: n === undefined || replayDay ? "—" : t("ops.radar.badge", { n }), hot: false };
    }
    const mine = items.filter((i) => i.axis === a.id);
    const open = mine.filter((i) => i.state !== "resolved").length;
    const ahead = upcoming[a.id] ?? 0;
    const countText =
      mine.length === 0
        ? ahead > 0
          ? t("ops.radar.badge", { n: ahead })
          : "—"
        : ahead > 0
          ? t("ops.radar.axisCountUpcoming", { open, total: mine.length, n: ahead })
          : t("ops.radar.axisCount", { open, total: mine.length });
    return { id: a.id, label: axisLabel(a.id), countText, hot: mine.some((i) => i.state === "action") };
  });
  const chips = [
    ...RADAR_AXES.filter((a) => !a.badge).map((a) => {
      const mine = items.filter((i) => i.axis === a.id);
      return { id: a.id, total: mine.length, hot: mine.some((i) => i.state === "action") };
    }),
    ...(HIDDEN_AXES.has("expiry") ? [] : [{ id: "expiry" as AxisId, total: expiryList.length, hot: expiryList.some((d) => d.tier === "critical") }]),
  ];
  // Departures: each band is the base-local clock that far ahead. Live, `centreMs` ticks; a replay uses that day's centre.
  // Arrivals stay hour offsets (4H … 24H): those rings are age, hours behind the centre.
  const ringClock = (hoursAhead: number) => formatClock(centreMs + hoursAhead * 3_600_000, zone);
  const scopeRings: ScopeRing[] =
    mode === "departures"
      ? DEPARTURE_BANDS_HOURS.map((h) => ({ radius: departureRadius(h * 60), label: ringClock(h) }))
      : Array.from({ length: RINGS }, (_, i) => (i + 1) * RING_HOURS).map((h) => ({ radius: radiusFor(h * 60), label: t("ops.radar.ringLabel", { h }) }));
  const scopeCentre = mode === "departures" ? { radius: DEPARTURE_CORE_RADIUS, className: "radar-ring--core" } : { radius: radiusFor(RING_HOURS * 60), className: "radar-ring--now" };
  // The scope's heading, in the order its parts are dropped when the row is short (last first): the whole text is also its hover.
  const rangeText = t(mode === "departures" ? "ops.radar.rangeDepartures" : "ops.radar.range");
  const onScopeText = view === "resolved" ? t("ops.radar.onScopeResolved") : t("ops.radar.onScopeActionable");
  const sweepText = t("ops.radar.sweep", { n: SWEEP_SECONDS });
  const noteText = replayDay
    ? t(mode === "departures" ? "ops.radar.bandNoteReplay" : "ops.radar.ringNoteReplay", { time: clockAt(centreMinutes) })
    : t(mode === "departures" ? "ops.radar.bandNote" : "ops.radar.ringNote");
  const headingText = [t("ops.radar.scopeTitle"), rangeText, onScopeText, ...(replayDay ? [] : [sweepText]), noteText].join(" · ");
  const switchMode = (next: RadarMode) => {
    if (next === mode) return;
    resetView();
    storeMode(next);
    setRemembered(next);
    setParams((prev) => {
      const params = new URLSearchParams(prev);
      if (next === "arrivals") params.delete("mode");
      else params.set("mode", next);
      return params;
    });
  };

  return (
    <div className="radar-screen" data-testid="radar-screen" ref={screenRef}>
      <header className="radar-head">
        <span className="radar-head-logo">
          <img src={DCORTEX_MARK} alt={t("ops.logoAlt")} />
        </span>
        <TenantMark className="radar-head-tenant" alt={t("shell.tenantLogo")} />
        <div className="radar-brand">
          <svg width="34" height="34" viewBox="0 0 34 34" aria-hidden="true">
            <circle cx="17" cy="17" r="15" className="radar-brand-ring" />
            <circle cx="17" cy="17" r="9" className="radar-brand-ring radar-brand-ring--inner" />
            <path d="M17 17 L17 2" className="radar-brand-beam" />
            <circle cx="24" cy="11" r="2.4" className="radar-brand-blip" />
          </svg>
          <span className="radar-brand-title">{t("ops.radar.subtitle")}</span>
        </div>
        <span className="radar-head-gap" />
        <span className="radar-days" role="group" aria-label={t("ops.radar.days")}>
          <button type="button" className="radar-day-step" data-testid="radar-day-prev" aria-label={t("ops.radar.dayPrev")} onClick={() => goToDay(addLocalDays(replayDay ?? today, -1))}>
            ◀
          </button>
          <span className="radar-day-label">{dayLabel(replayDay ?? today, ctx.locale)}</span>
          <button
            type="button"
            className="radar-day-step"
            data-testid="radar-day-next"
            aria-label={t("ops.radar.dayNext")}
            title={replayDay ? undefined : t("ops.radar.outlookSoon")}
            disabled={!replayDay}
            onClick={() => replayDay && goToDay(addLocalDays(replayDay, 1) >= today ? undefined : addLocalDays(replayDay, 1))}
          >
            ▶
          </button>
          {replayDay && (
            <button type="button" className="radar-day-live" data-testid="radar-day-live" onClick={() => goToDay(undefined)}>
              {t("ops.radar.live")}
            </button>
          )}
        </span>
        {replayDay ? (
          <span className="radar-feed-pill radar-feed-pill--replay" data-testid="radar-feed-pill" role="status">
            {t("ops.radar.replay", { day: dayLabel(replayDay, ctx.locale), time: clockAt(centreMinutes) })}
          </span>
        ) : (
          <span className={stale ? "radar-feed-pill radar-feed-pill--stale" : "radar-feed-pill"} data-testid="radar-feed-pill" role="status">
            <span className="radar-live-dot" />
            {stale ? t("ops.radar.feedStale", { n: updatedAgo }) : t("ops.radar.feedLive", { n: updatedAgo })}
          </span>
        )}
        <span className="radar-clock">
          <span className="radar-clock-time" data-testid="radar-clock-local">
            {`${hhmm(nowIso, zone)}:${String(Math.floor(nowMs / 1000) % 60).padStart(2, "0")}`}
          </span>
          <span className="radar-clock-label">{zoneCity(zone, client.presentation()).toUpperCase()}</span>
        </span>
        <span className="radar-clock radar-clock--utc">
          <span className="radar-clock-time" data-testid="radar-clock-utc">
            {hhmm(nowIso, "UTC")}
          </span>
          <span className="radar-clock-label">{t("ops.radar.utc")}</span>
        </span>
        {presentation?.customerName && <span className="radar-tenant">{presentation.customerName}</span>}
        <button type="button" className="radar-head-button" data-testid="radar-fullscreen" onClick={() => screenRef.current && requestFullscreen(screenRef.current)}>
          {t("ops.radar.fullscreen")}
        </button>
      </header>

      <div className="radar-main">
        <section className="radar-feed" aria-label={t("ops.radar.feedTitle")}>
          <div className="radar-feed-head">
            <div>
              <span className="radar-eyebrow">{t(mode === "departures" ? "ops.radar.eyebrowDepartures" : "ops.radar.eyebrow")}</span>
              <h1>{t("ops.radar.feedTitle")}</h1>
            </div>
          </div>

          <div className="radar-kpis" role="group" aria-label={t("ops.radar.tiles")}>
            {(
              [
                ["action", counts.action],
                ["open", counts.open],
                ["new", items.filter(isNew).length],
                ["resolved", items.length - counts.open],
              ] as const
            ).map(([id, n]) => (
              <button key={id} type="button" className={`radar-kpi radar-kpi--${id}`} data-testid={`radar-tile-${id}`} aria-pressed={view === id} onClick={() => toggleView(id)}>
                <span className="radar-kpi-value" data-testid={`radar-kpi-${id}`} aria-busy={!loaded && !loadFailed}>
                  {loaded || loadFailed ? n : <span className="ops-skel ops-skel--num" role="status" aria-label={t("ops.radar.loading")} />}
                </span>
                <span className="radar-kpi-label">{t(`ops.radar.kpi.${id}`)}</span>
              </button>
            ))}
          </div>

          <div className="radar-chips" role="group" aria-label={t("ops.radar.chips")}>
            <button type="button" className="radar-chip" data-testid="radar-chip-all" aria-pressed={listOpen && !filtered} onClick={pressAll}>
              {t("ops.radar.chipAll", { n: items.length })}
            </button>
            {chips.map((c) => (
              <button key={c.id} type="button" className={c.hot ? "radar-chip radar-chip--hot" : "radar-chip"} data-testid={`radar-chip-${c.id}`} aria-pressed={filter === c.id} onClick={() => toggleFilter(c.id)}>
                {t(`ops.radar.short.${c.id}`)} · {c.total}
              </button>
            ))}
          </div>

          {popupGap && (
            <CheckInAlertModal
              client={client}
              path={`/api/read/crew-check-in-gaps?date=${popupGap.day ?? reads.checkIns?.day ?? ""}`}
              detail={{ flight: popupGap.flight, dep: popupGap.dep, arr: popupGap.arr }}
              anchor={popupGap.std ?? undefined}
              crew={checkInGaps?.filter((g) => g.day === popupGap.day) as unknown as Record<string, unknown>[]}
              day={popupGap.day ?? reads.checkIns?.day ?? ""}
              ctx={ctx}
              t={t}
              onClose={closePopup}
            />
          )}
          {popupConnection && (
            <ConnectionAlertModal
              client={client}
              path={`/api/read/turnaround-risks?date=${popupConnection.day ?? reads.turnaround?.day ?? ""}`}
              item={rowIdentity.connection(popupConnection)}
              detail={{
                inboundStation: popupConnection.inbound.dep,
                connectionStation: popupConnection.connectionStation,
                arr: popupConnection.outbound.arr,
                actualGapMins: popupConnection.turnaround.actualGapMins,
                requiredMins: popupConnection.turnaround.severity === "CRITICAL" ? popupConnection.turnaround.criticalMins : popupConnection.turnaround.warningMins,
              }}
              severity={popupConnection.turnaround.severity === "CRITICAL" ? "crit" : "warn"}
              ctx={ctx}
              t={t}
              onClose={closePopup}
              onAct={(outbound, position) => {
                const flight = heldFlight(outbound.flightNo, outbound.dep, outbound.arr, outbound.std);
                if (!flight) return;
                setPopupFor(undefined);
                void showFlight(flight, true, position);
              }}
            />
          )}
          {selected && (
            <div className="radar-locked" data-testid="radar-locked">
              <button type="button" className="radar-x radar-locked-close" data-testid="radar-locked-close" aria-label={t("ops.radar.close")} title={t("ops.radar.close")} onClick={() => setSelectedId(undefined)}>
                ×
              </button>
              <div className="radar-locked-head">
                <div>
                  <div className="radar-locked-title">
                    {lockTitle(t, selected)}
                    {selected.kind === "flight" && selected.route ? <span className="radar-locked-kind"> · {selected.route}</span> : null}
                  </div>
                  {selected.kind === "task" && <div className="radar-locked-kind">{t(`ops.radar.axis.${selected.axis}`)}</div>}
                </div>
                <span className={`radar-pill radar-pill--${pill(selected)}`}>{t(`ops.radar.pill.${pill(selected)}`)}</span>
              </div>
              <div className="radar-locked-facts">
                {lockFacts(t, selected, ctx).map((fact) => (
                  <div key={fact.label} className="radar-locked-fact">
                    <span className="radar-locked-fact-label">{fact.label}</span>
                    <span className="radar-locked-fact-value">{fact.value}</span>
                  </div>
                ))}
              </div>
              {selected.taskId && (
                <div className="radar-locked-actions">
                  {selected.state === "action" && !replayDay && (
                    <button type="button" className={`radar-primary${ackingId === selected.taskId ? " radar-busy" : ""}`} data-testid="radar-acknowledge" disabled={ackingId === selected.taskId} aria-busy={ackingId === selected.taskId} onClick={() => void acknowledge(selected.taskId!)}>
                      {ackingId === selected.taskId ? t("ops.radar.acknowledging") : t("ops.radar.acknowledge")}
                    </button>
                  )}
                  {ackFailed === selected.taskId && (
                    <span className="radar-ack-error" data-testid="radar-ack-error" role="alert">
                      {t("ops.radar.ackFailed")}
                    </span>
                  )}
                  <button type="button" className="radar-secondary" data-testid="radar-open-task" onClick={() => setTaskModalId(selected.taskId)}>
                    {t("ops.radar.openTask")}
                  </button>
                </div>
              )}
              {(detailGap || detailConnection) && (
                <div className="radar-locked-actions">
                  <button type="button" className="radar-secondary" onClick={() => setPopupFor(selected.id)}>
                    {t("ops.radar.details")}
                  </button>
                </div>
              )}
              {selected.kind === "flight" && (selected.axis === "uncrewed" || selected.axis === "delay" || selected.axis === "cancel") && selected.legId && (
                <div className="radar-locked-actions">
                  <button type="button" className={`radar-secondary${openingId === selected.legId ? " radar-busy" : ""}`} data-testid="radar-open-flight" disabled={openingId === selected.legId} aria-busy={openingId === selected.legId} onClick={() => void openHeldFlight(selected.legId!, selected.axis)}>
                    {openingId === selected.legId ? t("ops.radar.opening") : selected.axis === "cancel" ? t("ops.radar.openFlight") : t("ops.radar.openTask")}
                  </button>
                  {openFailedId === selected.legId && (
                    <span className="radar-ack-error" data-testid="radar-open-failed" role="alert">
                      {t("ops.radar.flightUnavailable")}
                    </span>
                  )}
                </div>
              )}
            </div>
          )}

          {stale && (
            <p className="radar-stale" data-testid="radar-stale" role="status">
              {t("ops.radar.stale")}
            </p>
          )}

          {listOpen && (listing.length > 0 || filter === "expiry") && (
          <div className="radar-filterbar">
            <span className="radar-shown" data-testid="radar-shown">
              {filter === "expiry"
                ? t("ops.radar.expiryShown", { n: expiryList.length })
                : filter || view
                  ? t("ops.radar.shownFiltered", { n: shown.length, total: listing.length, axis: [view && t(`ops.radar.kpi.${view}`), filter && t(`ops.radar.short.${filter}`)].filter(Boolean).join(" · ") })
                  : t("ops.radar.shownAll", { n: items.length })}
            </span>
            <button
              type="button"
              className="radar-x"
              data-testid="radar-clear-filters"
              aria-label={t("ops.radar.clearFilters")}
              title={t("ops.radar.clearFilters")}
              onClick={clearFilters}
            >
              ×
            </button>
          </div>
          )}

          {filter === "expiry" ? (
            listOpen && (
            <div className="radar-list" data-testid="radar-expiry-list">
              {reads.expiry === undefined ? (
                <p className="radar-empty ui-loading" data-testid="radar-loading" role="status">
                  {t("ops.radar.loading")}
                </p>
              ) : expiryList.length === 0 ? (
                <p className="radar-empty" data-testid="radar-expiry-empty">
                  {t("ops.radar.expiryEmpty")}
                </p>
              ) : (
                expiryList.map((doc) => (
                  <button type="button" key={`${doc.crewId}:${doc.docType}:${doc.expiryDate}`} className={`radar-row radar-row--expiry${doc.tier === "critical" ? " radar-row--action" : doc.tier === "warning" ? " radar-row--open" : ""}`} data-testid={`radar-expiry-row-${doc.crewId}-${doc.docType}`} title={formatLocalDate(doc.expiryDate, ctx)} onClick={() => setDocDetail(doc)}>
                    <span className="radar-row-when">
                      <span className="radar-row-age">{formatLocalDateShort(doc.expiryDate)}</span>
                      <span className="radar-row-clock">{t("ops.radar.expiryExpires")}</span>
                    </span>
                    <span className="radar-row-text">
                      <span className="radar-row-title">{doc.displayName ?? doc.crewId}</span>
                      <span className="radar-row-detail">{doc.docDescription ? `${doc.docType} — ${doc.docDescription}` : doc.docType}</span>
                    </span>
                    {doc.tier && <span className={`radar-pill radar-pill--${doc.tier === "critical" ? "cancelled" : doc.tier === "warning" ? "delayed" : "new"}`}>{t(`docExpiry.tier.${doc.tier}`)}</span>}
                  </button>
                ))
              )}
            </div>
            )
          ) : !loaded ? (
            loadFailed ? (
              <p className="radar-empty" data-testid={replayFlightsFailed ? "radar-replay-failed" : "radar-load-failed"} role="alert">
                {t(replayFlightsFailed ? "ops.radar.replayFailed" : "ops.radar.loadFailed")}
              </p>
            ) : (
              <p className="radar-empty ui-loading" data-testid={replayDay !== undefined && reads.tasks !== undefined ? "radar-replay-loading" : "radar-loading"} role="status">
                {t(replayDay !== undefined && reads.tasks !== undefined ? "ops.radar.replayLoading" : "ops.radar.loading")}
              </p>
            )
          ) : listing.length === 0 ? (
            aheadPending ? (
              <p className="radar-empty ui-loading" data-testid="radar-loading" role="status">
                {t("ops.radar.loading")}
              </p>
            ) : (
              <p className="radar-empty" data-testid="radar-empty">
                {t(mode === "departures" ? "ops.radar.emptyDepartures" : "ops.radar.empty")}
              </p>
            )
          ) : (
            listOpen && (
            <div className="radar-list">
              {shown.length === 0 && (
                <p className="radar-no-match" data-testid="radar-no-match">
                  {t("ops.radar.noMatch")}{" "}
                  <button type="button" className="radar-link" onClick={clearFilters}>
                    {t("ops.radar.clearFilters")}
                  </button>
